import com.github.javaparser.JavaParser;
import com.github.javaparser.ParserConfiguration;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.expr.MethodCallExpr;
import com.github.javaparser.symbolsolver.JavaSymbolSolver;
import com.github.javaparser.symbolsolver.resolution.typesolvers.ReflectionTypeSolver;

public class VerifyTextBlock {
    public static void main(String[] args) {
        String code = "public class MyExample {\n"
                + "  public static void main(String[] args) {\n"
                + "    \"Hello single %s!\".formatted(\"world\");\n"
                + "    \"\"\"\n"
                + "        Hello multiple %s!\n"
                + "        \"\"\".formatted(\"world\");\n"
                + "    String.format(\"\"\"\n"
                + "        Hello multiple %s!\n"
                + "        \"\"\", \"world\");\n"
                + "  }\n"
                + "}";
        ParserConfiguration config = new ParserConfiguration()
                .setLanguageLevel(ParserConfiguration.LanguageLevel.JAVA_21)
                .setSymbolResolver(new JavaSymbolSolver(new ReflectionTypeSolver(false)));
        CompilationUnit cu = new JavaParser(config).parse(code).getResult().get();
        cu.findAll(MethodCallExpr.class).forEach(m -> System.out.println(m + " -> " + m.resolve().getQualifiedSignature()));
    }
}

